use anyhow::{Result,Context,bail};
#[derive(Clone,Copy,Debug)]pub struct UiSettings{pub top:bool,pub kill_log:bool,pub player_panels:bool,pub overhead:bool,pub minimap:bool,pub events:bool}
impl Default for UiSettings{fn default()->Self{Self{top:true,kill_log:true,player_panels:true,overhead:true,minimap:true,events:true}}}
impl UiSettings{pub fn flags(self)->u8{self.top as u8|((self.kill_log as u8)<<1)|((self.player_panels as u8)<<2)|((self.overhead as u8)<<3)|((self.minimap as u8)<<4)|((self.events as u8)<<5)}}
#[derive(Clone,Copy,Debug)]pub struct Settings{pub ui:UiSettings,pub render_scale:f32,pub msaa_samples:u32,pub hud_width:u32,pub minimum_line_pixels:f32}
impl Default for Settings{fn default()->Self{Self{ui:UiSettings::default(),render_scale:1.4,msaa_samples:4,hud_width:2048,minimum_line_pixels:1.25}}}
impl Settings{
 pub fn parse(text:&str)->Result<Self>{let mut s=Self::default();for line in text.lines(){let line=line.split('#').next().unwrap().trim();if line.is_empty(){continue;}let(k,v)=line.split_once('=').context("viewer.toml: key = value 형식 필요")?;let v=v.trim();match k.trim(){"ui_top"=>s.ui.top=v.parse()?,"ui_kill_log"=>s.ui.kill_log=v.parse()?,"ui_player_panels"=>s.ui.player_panels=v.parse()?,"ui_overhead"=>s.ui.overhead=v.parse()?,"ui_minimap"=>s.ui.minimap=v.parse()?,"ui_events"=>s.ui.events=v.parse()?,"render_scale"=>s.render_scale=v.parse()?,"msaa_samples"=>s.msaa_samples=v.parse()?,"hud_width"=>s.hud_width=v.parse()?,"minimum_line_pixels"=>s.minimum_line_pixels=v.parse()?,"lang"=>if !matches!(v,"auto"|"ko"|"en"){bail!("lang 은 auto/ko/en");},k=>bail!("viewer.toml: 알 수 없는 설정 {k}")}}if !s.render_scale.is_finite()||!(0.5..=3.0).contains(&s.render_scale){bail!("render_scale 허용 범위 0.5~3.0");}if ![1,4].contains(&s.msaa_samples){bail!("msaa_samples는 1 또는 4");}if ![1024,2048,4096].contains(&s.hud_width){bail!("hud_width는 1024/2048/4096");}if !s.minimum_line_pixels.is_finite()||!(0.5..=3.0).contains(&s.minimum_line_pixels){bail!("minimum_line_pixels 허용 범위 0.5~3.0");}Ok(s)}
 pub fn load()->Result<Self>{let p=crate::log::root().join("viewer.toml");if p.exists(){Self::parse(&std::fs::read_to_string(p)?)}else{Ok(Self::default())}}
 pub fn eye_size(&self,recommended:[u32;2],max:[u32;2])->[u32;2]{std::array::from_fn(|i|((recommended[i]as f32*self.render_scale).round()as u32).clamp(1,max[i].max(1)))}
}
#[cfg(test)]mod tests{use super::*;#[test]fn ui_toggles_parse_without_changing_quality(){let s=Settings::parse("ui_player_panels = false\nui_minimap = false\nui_events = true").unwrap();assert!(!s.ui.player_panels&&!s.ui.minimap&&s.ui.events&&s.ui.top);assert_eq!(s.render_scale,1.4);assert_eq!(s.msaa_samples,4);assert!(Settings::parse("ui_top = maybe").is_err());}
#[test]fn scale_is_bounded_by_runtime(){let s=Settings::default();assert_eq!(s.eye_size([1632,1760],[4096,4096]),[2285,2464]);assert_eq!(s.eye_size([1632,1760],[2000,2000]),[2000,2000]);assert!(Settings::parse("render_scale = NaN").is_err());assert!(Settings::parse("msaa_samples = 3").is_err());}}
